<script setup lang="ts">
import {computed,onMounted,onUnmounted,ref} from 'vue'
import {useRoute} from 'vue-router'
import {api} from '@/api/client'
import {agentApi} from '@/api/agent'
import type {Run} from '@/api/types'
import {renderMarkdown} from '@/shared/markdown'
import SessionFork from '@/components/reader/SessionFork.vue'
const route=useRoute(),id=String(route.params.id)
interface Event {seq:number;kind:string;payload:{text?:string;[key:string]:unknown};created_at:string}
const run=ref<Run|null>(null),events=ref<Event[]>([]),manifest=ref<{authorized:Record<string,unknown>[];actual:Record<string,unknown>[];legacy?:boolean}>({authorized:[],actual:[]}),error=ref(''),after=ref(0),more=ref(false),selected=ref<number|null>(null),forkOpen=ref(false)
let timer:ReturnType<typeof setTimeout>|null=null,stopped=false,refreshing=false
const replay=computed(()=>{let text='';for(const e of events.value){if(selected.value!==null&&e.seq>selected.value)break;if(e.kind==='text_delta')text+=e.payload.text||'';else if(e.kind==='text_reset')text=e.payload.text||''}return text})
async function refresh(){if(refreshing||stopped)return;refreshing=true;if(timer)clearTimeout(timer);try{const [r,t,m]=await Promise.all([agentApi.getRun(id),api<{events:Event[];next_after:number;has_more:boolean}>(`/api/agent/runs/${id}/timeline?after=${after.value}&limit=200`),api<typeof manifest.value>(`/api/agent/runs/${id}/materials`)]);if(stopped)return;run.value=r;events.value.push(...t.events);after.value=t.next_after;more.value=t.has_more;manifest.value=m;error.value='';if(['queued','running'].includes(r.status)||more.value)timer=setTimeout(refresh,1000)}catch(e){error.value=String(e)}finally{refreshing=false}}
onMounted(refresh);onUnmounted(()=>{stopped=true;if(timer)clearTimeout(timer)})
</script>
<template><main class="inspector"><RouterLink to="/?home=1">Firework · 首页</RouterLink><h1>运行检查</h1><p v-if="error" role="alert">{{error}} <button @click="refresh">重试</button></p><template v-if="run"><header><strong>{{run.id}}</strong><span>{{run.status}}</span><span>{{run.model}}</span><a :href="`/api/agent/runs/${id}/debug-bundle`">下载脱敏调试包</a><button v-if="run.conversation_id" @click="forkOpen=true">创建会话分支</button></header><details open><summary>生效配置</summary><pre>{{JSON.stringify(run.diagnostics,null,2)}}</pre></details><h2>材料</h2><p v-if="manifest.legacy">旧任务没有完整材料快照，不推断实际阅读范围。</p><div class="columns"><section><h3>授权材料</h3><pre>{{JSON.stringify(manifest.authorized,null,2)}}</pre></section><section><h3>实际已读</h3><pre>{{JSON.stringify(manifest.actual,null,2)}}</pre></section></div><h2>事件与只读回放</h2><p v-if="!events.length">没有持久事件；历史任务仍可查看已保存结果。</p><button @click="selected=null">显示最新回放</button><ol><li v-for="e in events" :key="e.seq"><button @click="selected=e.seq">#{{e.seq}} {{e.kind}} · {{e.created_at}}</button><details v-if="!['text_delta','text_reset'].includes(e.kind)"><summary>事件数据</summary><pre>{{JSON.stringify(e.payload,null,2)}}</pre></details></li></ol><button v-if="more" @click="refresh">读取后续事件</button><h3>回放正文</h3><div class="markdown-content" v-html="renderMarkdown(replay)"></div><h2>已保存结果</h2><div class="markdown-content" v-html="renderMarkdown(run.answer||'')"></div><SessionFork v-if="forkOpen&&run.conversation_id" :session-id="run.conversation_id" @close="forkOpen=false"/></template></main></template>
<style scoped>.inspector{max-width:1100px;margin:auto;padding:24px}.inspector header{display:flex;gap:12px;flex-wrap:wrap;align-items:center}.columns{display:grid;grid-template-columns:1fr 1fr;gap:16px}pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px;background:var(--bg-soft);padding:12px}li{padding:4px}.markdown-content{overflow-wrap:anywhere}@media(max-width:700px){.columns{grid-template-columns:1fr}}</style>
